import json,re
from collections import Counter,defaultdict
arts=json.loads(open('data/articles.json',encoding='utf-8').read())
rows=[a['title'] for a in arts if a.get('section')=='thu-vien' and a.get('topicLv2Label')=='Tài khoản - Hạch toán']
patterns={
 'Tiền - ngân hàng':r'\b(tiền|ngân hàng|tiền gửi|quỹ|ngoại tệ)\b',
 'Doanh thu - chi phí':r'\b(doanh thu|chi phí|giá vốn|kết chuyển|lãi|lỗ)\b',
 'TSCĐ - CCDC':r'\b(tscđ|tài sản cố định|ccdc|công cụ dụng cụ|khấu hao)\b',
 'Hàng tồn kho':r'\b(hàng hóa|hàng tồn kho|nguyên vật liệu|vật liệu|thành phẩm|kho)\b',
 'Công nợ - thanh toán':r'\b(công nợ|phải thu|phải trả|thanh toán|tạm ứng|vay)\b',
 'Thuế':r'\b(thuế|gtgt|tncn|tndn|môn bài)\b',
 'Lương - bảo hiểm':r'\b(lương|bhxh|bhyt|bhtn|công đoàn)\b',
 'Đầu tư - vốn':r'\b(đầu tư|vốn|cổ phiếu|liên doanh|liên kết)\b',
}
counts=Counter()
examples=defaultdict(list)
for t in rows:
    matched=False
    low=t.lower()
    for name,pat in patterns.items():
        if re.search(pat,low):
            counts[name]+=1
            if len(examples[name])<6: examples[name].append(t)
            matched=True
    if not matched:
        counts['Khác']+=1
        if len(examples['Khác'])<10: examples['Khác'].append(t)
print('count',len(rows))
for name,n in counts.most_common():
    print(f'\n## {name}: {n}')
    for t in examples[name]:
        print('-',t)
